// Some portions generated by Claude

/** What one press of Escape closes on the Graph page, topmost first. */
export type EscapeLayer = "menu" | "card" | "selection" | "none";

/**
 * Escape closes the topmost thing: an open menu (a toolbar popover or the node menu) and nothing else; otherwise the
 * node or statement card together with the highlight it explains; otherwise the selection made by clicks, boxes and
 * menu items. Filters stay, as they do for a click on the background.
 */
export function escapeStep(open: { menu: boolean; card: boolean; selection: boolean }): EscapeLayer {
  if (open.menu) return "menu";
  if (open.card) return "card";
  return open.selection ? "selection" : "none";
}
